WITH valid AS (SELECT *, DATE_FORMAT(delivered_date, 'yyyy-MM-dd') AS delivered_date_label, COALESCE(carrier, 'UNKNOWN') AS carrier_filled FROM shipments WHERE shipped_date >= DATE '2023-07-13' AND order_id = 37), metrics AS (SELECT *, MAX(cost) OVER w_running AS last7_max_cost, COUNT(cost) OVER w_running AS last7_count_cost, MIN(cost) OVER w_running AS last7_min_cost FROM valid WINDOW w_running AS (PARTITION BY status, carrier ORDER BY shipped_date ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), joined AS (SELECT src.*, p.status AS order_status, p.amount FROM metrics src LEFT JOIN orders p ON src.order_id <=> p.id WHERE p.order_date > '2024-06-30'), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY shipped_date DESC NULLS LAST, id ASC) AS row_num FROM joined) t WHERE row_num = 1), latest AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY order_status, status ORDER BY cost DESC) AS row_num_2 FROM ranked) ranked WHERE row_num_2 = 1), scored AS (SELECT *, MIN(last7_min_cost) OVER (PARTITION BY order_id) AS order_id_min_last7_min_cost, FIRST_VALUE(last7_min_cost) IGNORE NULLS OVER (PARTITION BY carrier ORDER BY last7_count_cost ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_last7_min_cost FROM latest) SELECT CASE WHEN last7_count_cost >= 18 THEN 'PREMIUM' ELSE 'STANDARD' END AS last7_count_cost_tier, order_id, DATE_TRUNC('MONTH', delivered_date) AS activity_month, AVG(last7_count_cost) AS avg_last7_count_cost, COUNT(*) FILTER (WHERE order_status = 'CANCELLED') AS cancelled_rows, COUNT(*) FILTER (WHERE order_status = 'COMPLETED') AS completed_rows, COUNT(*) FILTER (WHERE carrier = 'FedEx') AS fedex_rows, GROUPING(CASE WHEN last7_count_cost >= 18 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM scored GROUP BY ROLLUP (CASE WHEN last7_count_cost >= 18 THEN 'PREMIUM' ELSE 'STANDARD' END, order_id, DATE_TRUNC('MONTH', delivered_date)) HAVING AVG(last7_count_cost) > 0 ORDER BY order_id ASC NULLS FIRST;
